        Files.deleteIfExists(file);
        List<Todo> asli = Arrays.asList(new Todo(1, "Kopi, gula", false), new Todo(2, "Baris\nbaru", true));
        TodoCsv.ekspor(asli, file);
        HasilImpor hasil = TodoCsv.impor(file);
        System.out.println(hasil.berhasil.size() + " todo, " + hasil.kesalahan.size() + " kesalahan");
