import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

import org.apache.commons.csv.*;

public class Main {
    public static void main(String[] args) throws IOException {
        Path file = Paths.get("impor-tantangan.csv");
        Files.deleteIfExists(file);
        StringBuilder isi = new StringBuilder();
        Scanner in = new Scanner(System.in);
        while (in.hasNextLine()) {
            isi.append(in.nextLine()).append("\n");
        }
        Files.write(file, isi.toString().getBytes(StandardCharsets.UTF_8));
        HasilImpor hasil = TodoCsv.impor(file);
        for (Todo t : hasil.berhasil) {
            System.out.println(t);
        }
        for (String k : hasil.kesalahan) {
            System.out.println(k);
        }
    }
}

class Todo {
    private final int id;
    private final String judul;
    private final boolean selesai;

    Todo(int id, String judul, boolean selesai) {
        this.id = id;
        this.judul = judul;
        this.selesai = selesai;
    }

    int getId() {
        return id;
    }

    String getJudul() {
        return judul;
    }

    boolean isSelesai() {
        return selesai;
    }

    @Override
    public String toString() {
        return id + ". [" + (selesai ? "x" : " ") + "] " + judul;
    }
}

class HasilImpor {
    final List<Todo> berhasil = new ArrayList<>();
    final List<String> kesalahan = new ArrayList<>();
}

class TodoCsv {
    static final String[] KOLOM = {"id", "judul", "selesai"};
    private static final CSVFormat TULIS = CSVFormat.DEFAULT.builder().setHeader(KOLOM).build();
    private static final CSVFormat BACA = CSVFormat.DEFAULT.builder()
            .setHeader()
            .setSkipHeaderRecord(true)
            .setTrim(true)
            .build();

    static void ekspor(List<Todo> daftar, Path file) throws IOException {
        try (Writer w = Files.newBufferedWriter(file, StandardCharsets.UTF_8);
             CSVPrinter printer = new CSVPrinter(w, TULIS)) {
            for (Todo t : daftar) {
                printer.printRecord(t.getId(), t.getJudul(), t.isSelesai());
            }
        }
    }

    static HasilImpor impor(Path file) throws IOException {
        HasilImpor hasil = new HasilImpor();
        try (Reader r = Files.newBufferedReader(file, StandardCharsets.UTF_8);
             CSVParser parser = new CSVParser(r, BACA)) {
            for (String k : KOLOM) {
                if (!parser.getHeaderNames().contains(k)) {
                    hasil.kesalahan.add("Kolom " + k + " tidak ada");
                    return hasil;
                }
            }
            for (CSVRecord rec : parser) {
                long baris = rec.getRecordNumber() + 1;
                try {
                    hasil.berhasil.add(keTodo(rec));
                } catch (IllegalArgumentException e) {
                    hasil.kesalahan.add("Baris " + baris + ": " + e.getMessage());
                }
            }
        }
        return hasil;
    }

    private static Todo keTodo(CSVRecord r) {
        if (!r.isConsistent()) {
            throw new IllegalArgumentException("jumlah kolom tidak sesuai");
        }
        int id;
        try {
            id = Integer.parseInt(r.get("id"));
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("id bukan angka: " + r.get("id"));
        }
        String judul = r.get("judul");
        if (judul.isEmpty()) {
            throw new IllegalArgumentException("judul kosong");
        }
        String s = r.get("selesai").toLowerCase();
        if (!s.equals("true") && !s.equals("false")) {
            throw new IllegalArgumentException("selesai harus true atau false");
        }
        return new Todo(id, judul, Boolean.parseBoolean(s));
    }
}
